CREATE TABLE IF NOT EXISTS external_beneficiaries(id CHAR(36) PRIMARY KEY,customer_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,bank_code VARCHAR(30) NOT NULL,bank_name VARCHAR(160) NOT NULL,account_number VARCHAR(50) NOT NULL,currency CHAR(3) NOT NULL,status ENUM('PENDING_VERIFICATION','ACTIVE','INACTIVE') NOT NULL DEFAULT 'PENDING_VERIFICATION',verification_reference VARCHAR(180) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uq_external_beneficiary(customer_id,bank_code,account_number),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS beneficiary_step_up_authorizations(id CHAR(36) PRIMARY KEY,customer_id CHAR(36) NOT NULL,otp_challenge_id CHAR(36) NOT NULL,action ENUM('CREATE','UPDATE','DEACTIVATE') NOT NULL,beneficiary_id VARCHAR(100) NULL,expires_at DATETIME(3) NOT NULL,consumed_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(otp_challenge_id) REFERENCES otp_challenges(id) ON DELETE RESTRICT,INDEX idx_beneficiary_stepup(customer_id,action,expires_at));
